    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);showLoading();worker.execute(()->{try{verifyAssets();ResearchEngine.Data loaded=ResearchEngine.Data.read(assetReader("adjusted_prices.csv"),assetReader("risk_free.csv"),assetReader("allocations.csv"));double[] w=loaded.presets.get(name).clone();ResearchEngine.Analysis computed=ResearchEngine.analyze(loaded,w,name);ResearchEngine.Backtest b=ResearchEngine.backtest(loaded,w);ui.post(()->{data=loaded;weights=w;analysis=computed;validation=b;tested.put(key(w),b);layout();});}catch(Exception e){ui.post(()->errorScreen("The bundled research snapshot could not be verified. Reinstall the original APK. "+e.getClass().getSimpleName()));}});}
    private Reader assetReader(String file)throws IOException{return new InputStreamReader(getAssets().open(file),"UTF-8");}
    private String readAsset(String file)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();try(InputStream i=getAssets().open(file)){byte[] buf=new byte[8192];int n;while((n=i.read(buf))!=-1)b.write(buf,0,n);}return b.toString("UTF-8");}
    private void verifyAssets()throws Exception{dataset=new JSONObject(readAsset("dataset.json"));JSONObject hashes=dataset.getJSONObject("sha256");Iterator<String> keys=hashes.keys();while(keys.hasNext()){String f=keys.next();MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=getAssets().open(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)md.update(b,0,n);}StringBuilder hex=new StringBuilder();for(byte x:md.digest())hex.append(String.format(Locale.US,"%02x",x&255));if(!hex.toString().equals(hashes.getString(f)))throw new IOException("Snapshot integrity check failed");}}
    private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private GradientDrawable surface(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(10));d.setStroke(dp(1),LINE);return d;}
    private TextView text(String s,int size,int color,boolean serif){TextView v=new TextView(this);v.setText(s);v.setTextColor(color);v.setTextSize(size);v.setLineSpacing(dp(3),1);v.setTypeface(Typeface.create(serif?"serif":"sans-serif",Typeface.NORMAL));return v;}
